# ---- ItemEditorForm.cs
@'
using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Windows.Forms;

namespace ScreenCycle
{
    internal sealed class ItemEditorForm : Form
    {
        public RotationItem Result { get; private set; }
        private readonly RotationItem item;

        private RadioButton rbWeb, rbApp, rbWin;
        private TextBox tbName, tbUrl, tbPath, tbArgs, tbAppTitle, tbWinTitle, tbWinProc;
        private ComboBox cbBrowser, cbProfile, cbMode, cbCrop;
        private readonly List<string> profileIds = new List<string>();
        private Control profileLabel;
        private NumericUpDown nuCrop;
        private Control cropRow, cropLabel;
        private NumericUpDown nuDuration;
        private CheckBox ckRefresh, ckEnabled;
        private Label lbMatch, lbBrowserHint;
        private readonly List<Control> webRows = new List<Control>(), appRows = new List<Control>(), winRows = new List<Control>();
        private static readonly BrowserKind[] BrowserOrder = { BrowserKind.Auto, BrowserKind.Edge, BrowserKind.Chrome, BrowserKind.Firefox, BrowserKind.Brave, BrowserKind.Default };

        public ItemEditorForm(RotationItem source, bool isNew)
        {
            item = source.Clone();
            UiKit.PrepareForm(this);
            Text = isNew ? "Add a screen" : "Edit screen";
            FormBorderStyle = FormBorderStyle.FixedDialog;
            MaximizeBox = false;
            MinimizeBox = false;
            ShowInTaskbar = false;
            StartPosition = FormStartPosition.CenterParent;
            AutoSize = true;
            AutoSizeMode = AutoSizeMode.GrowAndShrink;
            Padding = new Padding(20, 16, 20, 16);
            Build();
            LoadItem(item);
        }

        private void AddRow(TableLayoutPanel t, string label, Control c, List<Control> group)
        {
            Label l = UiKit.Label(label);
            int r = t.RowCount++;
            t.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            t.Controls.Add(l, 0, r);
            t.Controls.Add(c, 1, r);
            if (group != null) { group.Add(l); group.Add(c); }
        }

        private void AddFull(TableLayoutPanel t, Control c, List<Control> group)
        {
            int r = t.RowCount++;
            t.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            t.Controls.Add(c, 1, r);
            if (group != null) group.Add(c);
        }

        private TextBox NewText(int width)
        {
            TextBox tb = new TextBox();
            tb.Width = width;
            tb.Margin = new Padding(0, 3, 6, 3);
            return tb;
        }

        private void Build()
        {
            TableLayoutPanel t = UiKit.Grid(2);
            t.MinimumSize = new Size(630, 0); // same width for every type, so the dialog doesn't jump
            int wide = 440;

            rbWeb = new RadioButton { Text = "Website", AutoSize = true, Margin = new Padding(0, 5, 16, 5) };
            rbApp = new RadioButton { Text = "Application or file", AutoSize = true, Margin = new Padding(0, 5, 16, 5) };
            rbWin = new RadioButton { Text = "Already open window", AutoSize = true, Margin = new Padding(0, 5, 0, 5) };
            EventHandler kindChanged = delegate { UpdateKind(); };
            rbWeb.CheckedChanged += kindChanged;
            rbApp.CheckedChanged += kindChanged;
            rbWin.CheckedChanged += kindChanged;
            AddRow(t, "Type", UiKit.Row(rbWeb, rbApp, rbWin), null);

            tbName = NewText(wide);
            AddRow(t, "Name", tbName, null);
            AddFull(t, UiKit.Hint("Optional — shown in the list and the tray menu."), null);

            // ---- website
            tbUrl = NewText(wide);
            AddRow(t, "Web address", tbUrl, webRows);
            cbBrowser = UiKit.Combo(wide);
            foreach (BrowserKind k in BrowserOrder) cbBrowser.Items.Add(Browsers.Describe(k));
            cbBrowser.SelectedIndexChanged += delegate { RefreshProfiles(SelectedProfileId()); UpdateBrowserHint(); };
            AddRow(t, "Browser", cbBrowser, webRows);
            cbProfile = UiKit.Combo(wide);
            cbProfile.SelectedIndexChanged += delegate { UpdateBrowserHint(); };
            AddRow(t, "Profile", cbProfile, webRows);
            profileLabel = t.GetControlFromPosition(0, t.RowCount - 1);
            lbBrowserHint = UiKit.Hint("");
            lbBrowserHint.MaximumSize = new Size(wide, 0);
            AddFull(t, lbBrowserHint, webRows);

            // ---- application
            tbPath = NewText(wide - 190);
            Button browse = UiKit.Button("Browse…", delegate { BrowseProgram(); });
            Button fromWin = UiKit.Button("From open app…", delegate { PickRunning(true); });
            AddRow(t, "Program or file", UiKit.Row(tbPath, browse, fromWin), appRows);
            tbArgs = NewText(wide);
            AddRow(t, "Arguments", tbArgs, appRows);
            tbAppTitle = NewText(wide);
            AddRow(t, "Window title has", tbAppTitle, appRows);
            Label appHint = UiKit.Hint("Programs, shortcuts (.lnk), documents (PDF, PowerPoint, pictures…) all work. The title filter is\noptional: use it when the app opens several windows, or to reuse a window that is already open.");
            AddFull(t, appHint, appRows);

            // ---- existing window
            tbWinTitle = NewText(wide);
            AddRow(t, "Window title has", tbWinTitle, winRows);
            tbWinProc = NewText(wide - 190);
            Button pick = UiKit.Button("Pick an open window…", delegate { PickRunning(false); });
            AddRow(t, "Process name", UiKit.Row(tbWinProc, pick), winRows);
            lbMatch = UiKit.Hint("");
            lbMatch.MaximumSize = new Size(wide, 0);
            AddFull(t, lbMatch, winRows);
            tbWinTitle.TextChanged += delegate { UpdateMatch(); };
            tbWinProc.TextChanged += delegate { UpdateMatch(); };

            // ---- common
            Panel sep = new Panel { Height = 1, Width = wide + 120, BackColor = UiKit.Border, Margin = new Padding(0, 10, 0, 10) };
            int rs = t.RowCount++;
            t.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            t.Controls.Add(sep, 0, rs);
            t.SetColumnSpan(sep, 2);

            nuDuration = UiKit.Number(1, 86400, 30, 80);
            AddRow(t, "Show for", UiKit.Row(nuDuration, UiKit.Label("seconds")), null);
            cbMode = UiKit.Combo(200, "Fullscreen", "Maximized", "Leave as is");
            AddRow(t, "Display", cbMode, null);
            cbCrop = UiKit.Combo(200, "Hide it automatically", "Keep it visible", "Cut off the top by");
            nuCrop = UiKit.Number(1, 400, 40, 64);
            Label px = UiKit.Label("pixels");
            cbCrop.SelectedIndexChanged += delegate { nuCrop.Visible = px.Visible = cbCrop.SelectedIndex == 2; };
            cbMode.SelectedIndexChanged += delegate { cropRow.Visible = cropLabel.Visible = cbMode.SelectedIndex == 0; };
            cropRow = UiKit.Row(cbCrop, nuCrop, px);
            AddRow(t, "App title bar", cropRow, null);
            cropLabel = t.GetControlFromPosition(0, t.RowCount - 1);
            ckRefresh = UiKit.Check("Refresh it (F5) each time it comes on screen", false);
            AddFull(t, ckRefresh, null);
            ckEnabled = UiKit.Check("Include in the rotation", true);
            AddFull(t, ckEnabled, null);

            // ---- buttons
            FlowLayoutPanel buttons = new FlowLayoutPanel();
            buttons.FlowDirection = FlowDirection.RightToLeft;
            buttons.AutoSize = true;
            buttons.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            buttons.WrapContents = false;
            buttons.Anchor = AnchorStyles.Right;
            buttons.Margin = new Padding(0, 16, 0, 0);
            Button ok = UiKit.Primary("OK", delegate { Accept(); });
            Button cancel = UiKit.Button("Cancel", null);
            cancel.DialogResult = DialogResult.Cancel;
            ok.Margin = new Padding(8, 0, 0, 0);
            cancel.Margin = new Padding(8, 0, 0, 0);
            buttons.Controls.Add(cancel);
            buttons.Controls.Add(ok);
            AcceptButton = ok;
            CancelButton = cancel;

            TableLayoutPanel root = UiKit.Grid(1);
            root.Location = new Point(Padding.Left, Padding.Top);
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.Controls.Add(t, 0, 0);
            root.Controls.Add(buttons, 0, 1);
            Controls.Add(root);
        }

        private void LoadItem(RotationItem i)
        {
            rbWeb.Checked = i.Kind == ItemKind.Website;
            rbApp.Checked = i.Kind == ItemKind.Application;
            rbWin.Checked = i.Kind == ItemKind.Window;
            tbName.Text = i.Name;
            tbUrl.Text = i.Url;
            cbBrowser.SelectedIndex = Math.Max(0, Array.IndexOf(BrowserOrder, i.Browser));
            RefreshProfiles(i.BrowserProfile ?? "");
            tbPath.Text = i.Path;
            tbArgs.Text = i.Arguments;
            tbAppTitle.Text = i.Kind == ItemKind.Application ? i.TitleContains : "";
            tbWinTitle.Text = i.Kind == ItemKind.Window ? i.TitleContains : "";
            tbWinProc.Text = i.ProcessName;
            nuDuration.Value = Math.Max(1, Math.Min(86400, i.DurationSeconds));
            cbMode.SelectedIndex = (int)i.Mode;
            cbCrop.SelectedIndex = i.TitleBarCrop < 0 ? 1 : i.TitleBarCrop == 0 ? 0 : 2;
            if (i.TitleBarCrop > 0) nuCrop.Value = Math.Min(400, i.TitleBarCrop);
            nuCrop.Visible = cbCrop.SelectedIndex == 2;
            cropRow.Visible = cropLabel.Visible = i.Mode == WindowMode.Fullscreen;
            ckRefresh.Checked = i.RefreshOnShow;
            ckEnabled.Checked = i.Enabled;
            UpdateKind();
        }

        private ItemKind Kind
        {
            get { return rbWeb.Checked ? ItemKind.Website : rbApp.Checked ? ItemKind.Application : ItemKind.Window; }
        }

        private void UpdateKind()
        {
            ItemKind k = Kind;
            SuspendLayout();
            foreach (Control c in webRows) c.Visible = k == ItemKind.Website;
            foreach (Control c in appRows) c.Visible = k == ItemKind.Application;
            foreach (Control c in winRows) c.Visible = k == ItemKind.Window;
            ResumeLayout(true);
            if (k == ItemKind.Window) UpdateMatch();
            if (k == ItemKind.Website) { ShowProfileRow(); UpdateBrowserHint(); }
        }

        private string SelectedProfileId()
        {
            int i = cbProfile.SelectedIndex;
            return i >= 0 && i < profileIds.Count ? profileIds[i] : "";
        }

        /// <summary>Fills the profile list for the chosen browser and selects <paramref name="want"/> when possible.</summary>
        private void RefreshProfiles(string want)
        {
            BrowserKind real = Browsers.Resolve(BrowserOrder[Math.Max(0, cbBrowser.SelectedIndex)]);
            cbProfile.BeginUpdate();
            cbProfile.Items.Clear();
            profileIds.Clear();
            cbProfile.Items.Add("Separate profile for this screen (private, log in once inside it)");
            profileIds.Add("");
            if (real != BrowserKind.Default)
            {
                foreach (BrowserProfileInfo p in Browsers.ListProfiles(real))
                {
                    cbProfile.Items.Add("My profile: " + p.Label);
                    profileIds.Add(p.Id);
                }
            }
            int sel = Math.Max(0, profileIds.IndexOf(want ?? ""));
            if (!string.IsNullOrEmpty(want) && profileIds.IndexOf(want) < 0)
            {
                cbProfile.Items.Add("Saved profile, not found on this PC: " + want);
                profileIds.Add(want);
                sel = profileIds.Count - 1;
            }
            cbProfile.SelectedIndex = sel;
            cbProfile.EndUpdate();
            ShowProfileRow();
        }

        private void ShowProfileRow()
        {
            bool show = Kind == ItemKind.Website && BrowserOrder[Math.Max(0, cbBrowser.SelectedIndex)] != BrowserKind.Default;
            cbProfile.Visible = profileLabel.Visible = show;
        }

        private void UpdateBrowserHint()
        {
            BrowserKind b = BrowserOrder[Math.Max(0, cbBrowser.SelectedIndex)];
            BrowserKind real = Browsers.Resolve(b);
            if (b != BrowserKind.Default && SelectedProfileId().Length > 0)
                lbBrowserHint.Text = "Opens in a new window of your own " + Browsers.Pretty(real) + " profile, so you are already signed in (Google, YouTube…). " +
                    "Works even while " + Browsers.Pretty(real) + " is open; ScreenCycle makes the window fullscreen with F11.";
            else if (b == BrowserKind.Default)
                lbBrowserHint.Text = "Opens in your normal browser. Fullscreen is applied by ScreenCycle; a dedicated browser below gives a cleaner kiosk view.";
            else if (Browsers.Find(b) == null && b != BrowserKind.Auto)
                lbBrowserHint.Text = "This browser is not installed on this PC — another installed browser will be used.";
            else
                lbBrowserHint.Text = "Opens in its own private browser window (kiosk style, no tabs or address bar). Logins you make in it are remembered for this screen.";
        }

        private void UpdateMatch()
        {
            RotationItem probe = new RotationItem();
            probe.Kind = ItemKind.Window;
            probe.TitleContains = tbWinTitle.Text;
            probe.ProcessName = tbWinProc.Text;
            if (string.IsNullOrWhiteSpace(probe.TitleContains) && string.IsNullOrWhiteSpace(probe.ProcessName))
            {
                lbMatch.ForeColor = UiKit.Muted;
                lbMatch.Text = "Fill in part of the window title and/or the process name (for example “chrome” or “EXCEL”).";
                return;
            }
            int count = 0;
            WindowInfo first = null;
            foreach (WindowInfo w in WindowTools.ListAppWindows(true))
            {
                if (ItemRuntime.MatchesWindowItem(probe, w)) { count++; if (first == null) first = w; }
            }
            if (count == 0)
            {
                lbMatch.ForeColor = UiKit.Warn;
                lbMatch.Text = "No open window matches right now. It will be used as soon as it is open.";
            }
            else
            {
                lbMatch.ForeColor = UiKit.Good;
                lbMatch.Text = "✓ Matches “" + Trim(first.Title, 60) + "”" + (count > 1 ? "  (and " + (count - 1) + " other" + (count > 2 ? "s" : "") + ")" : "");
            }
        }

        private static string Trim(string s, int n)
        {
            return s.Length <= n ? s : s.Substring(0, n - 1) + "…";
        }

        private void BrowseProgram()
        {
            using (OpenFileDialog d = new OpenFileDialog())
            {
                d.Title = "Choose a program or file";
                d.Filter = "Programs and shortcuts|*.exe;*.lnk;*.bat;*.cmd|All files|*.*";
                d.DereferenceLinks = false;
                try { if (File.Exists(tbPath.Text)) d.InitialDirectory = Path.GetDirectoryName(tbPath.Text); } catch { }
                if (d.ShowDialog(this) == DialogResult.OK)
                {
                    tbPath.Text = d.FileName;
                    if (tbName.Text.Trim().Length == 0) tbName.Text = Path.GetFileNameWithoutExtension(d.FileName);
                }
            }
        }

        private void PickRunning(bool forApp)
        {
            using (WindowPickerForm p = new WindowPickerForm())
            {
                if (p.ShowDialog(this) != DialogResult.OK || p.Selected == null) return;
                WindowInfo w = p.Selected;
                if (forApp)
                {
                    if (!string.IsNullOrEmpty(w.ProcessPath)) tbPath.Text = w.ProcessPath;
                    if (tbName.Text.Trim().Length == 0) tbName.Text = w.Title.Length > 0 ? Trim(w.Title, 40) : w.ProcessName;
                }
                else
                {
                    tbWinTitle.Text = w.Title;
                    tbWinProc.Text = w.ProcessName;
                    if (tbName.Text.Trim().Length == 0) tbName.Text = Trim(w.Title, 40);
                }
            }
        }

        private void Accept()
        {
            ItemKind k = Kind;
            if (k == ItemKind.Website && tbUrl.Text.Trim().Length == 0) { Complain(tbUrl, "Please enter a web address."); return; }
            if (k == ItemKind.Application && tbPath.Text.Trim().Length == 0) { Complain(tbPath, "Please choose a program or file."); return; }
            if (k == ItemKind.Window && tbWinTitle.Text.Trim().Length == 0 && tbWinProc.Text.Trim().Length == 0)
            { Complain(tbWinTitle, "Please enter part of the window title or the process name."); return; }
            if (k == ItemKind.Application)
            {
                string p = Environment.ExpandEnvironmentVariables(tbPath.Text.Trim().Trim('"'));
                bool looksLikePath = p.Contains("\\") || p.Contains("/");
                if (looksLikePath && !p.StartsWith("shell:", StringComparison.OrdinalIgnoreCase) && !File.Exists(p) && !Directory.Exists(p))
                {
                    if (MessageBox.Show(this, "This file doesn't exist:\n" + p + "\n\nKeep it anyway?", "ScreenCycle",
                        MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes) return;
                }
            }

            item.Kind = k;
            item.Name = tbName.Text.Trim();
            item.Url = tbUrl.Text.Trim();
            item.Browser = BrowserOrder[Math.Max(0, cbBrowser.SelectedIndex)];
            item.BrowserProfile = item.Browser == BrowserKind.Default ? "" : SelectedProfileId();
            item.Path = tbPath.Text.Trim().Trim('"');
            item.Arguments = tbArgs.Text.Trim();
            item.TitleContains = k == ItemKind.Application ? tbAppTitle.Text.Trim() : k == ItemKind.Window ? tbWinTitle.Text.Trim() : "";
            item.ProcessName = k == ItemKind.Window ? tbWinProc.Text.Trim() : "";
            item.DurationSeconds = (int)nuDuration.Value;
            item.Mode = (WindowMode)Math.Max(0, cbMode.SelectedIndex);
            item.RefreshOnShow = ckRefresh.Checked;
            item.TitleBarCrop = cbCrop.SelectedIndex == 1 ? -1 : cbCrop.SelectedIndex == 0 ? 0 : (int)nuCrop.Value;
            item.Enabled = ckEnabled.Checked;
            if (k == ItemKind.Website) item.Url = Browsers.NormalizeUrl(item.Url);
            Result = item;
            DialogResult = DialogResult.OK;
            Close();
        }

        private void Complain(Control c, string msg)
        {
            MessageBox.Show(this, msg, "ScreenCycle", MessageBoxButtons.OK, MessageBoxIcon.Information);
            c.Focus();
        }
    }

    internal sealed class WindowPickerForm : Form
    {
        private readonly ListView list;
        public WindowInfo Selected { get; private set; }

        public WindowPickerForm()
        {
            UiKit.PrepareForm(this);
            Text = "Pick an open window";
            StartPosition = FormStartPosition.CenterParent;
            ShowInTaskbar = false;
            MinimizeBox = false;
            ClientSize = new Size(640, 420);
            MinimumSize = new Size(480, 320);
            Padding = new Padding(16);

            Label hint = UiKit.Hint("Choose the window to put in the rotation. Open the app first if it is not listed.");
            hint.Dock = DockStyle.Top;

            list = new ListView();
            list.View = View.Details;
            list.FullRowSelect = true;
            list.HideSelection = false;
            list.MultiSelect = false;
            list.HeaderStyle = ColumnHeaderStyle.Nonclickable;
            list.Dock = DockStyle.Fill;
            list.Columns.Add("Window", 420);
            list.Columns.Add("Process", 160);
            UiKit.ModernList(list);
            list.DoubleClick += delegate { Choose(); };
            list.Resize += delegate { if (list.Columns.Count == 2) list.Columns[0].Width = Math.Max(150, list.ClientSize.Width - list.Columns[1].Width - 4); };

            FlowLayoutPanel buttons = new FlowLayoutPanel();
            buttons.FlowDirection = FlowDirection.RightToLeft;
            buttons.Dock = DockStyle.Bottom;
            buttons.AutoSize = true;
            buttons.Padding = new Padding(0, 12, 0, 0);
            Button ok = UiKit.Primary("Use this window", delegate { Choose(); });
            Button cancel = UiKit.Button("Cancel", null);
            cancel.DialogResult = DialogResult.Cancel;
            Button refresh = UiKit.Button("Refresh", delegate { Fill(); });
            ok.Margin = cancel.Margin = new Padding(8, 0, 0, 0);
            buttons.Controls.Add(cancel);
            buttons.Controls.Add(ok);
            buttons.Controls.Add(refresh);
            AcceptButton = ok;
            CancelButton = cancel;

            Controls.Add(list);
            Controls.Add(hint);
            Controls.Add(buttons);
            Fill();
        }

        private void Fill()
        {
            list.BeginUpdate();
            list.Items.Clear();
            List<WindowInfo> wins = WindowTools.ListAppWindows(true);
            wins.Sort(delegate(WindowInfo a, WindowInfo b) { return string.Compare(a.Title, b.Title, StringComparison.CurrentCultureIgnoreCase); });
            foreach (WindowInfo w in wins)
            {
                ListViewItem li = new ListViewItem(w.Title);
                li.SubItems.Add(w.ProcessName);
                li.Tag = w;
                list.Items.Add(li);
            }
            list.EndUpdate();
            if (list.Items.Count > 0) list.Items[0].Selected = true;
        }

        private void Choose()
        {
            if (list.SelectedItems.Count == 0) return;
            Selected = (WindowInfo)list.SelectedItems[0].Tag;
            DialogResult = DialogResult.OK;
            Close();
        }
    }
}
'@,
# ---- ItemRuntime.cs
@'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Management;
using System.Threading.Tasks;

namespace ScreenCycle
{
    /// <summary>Live state for one rotation item: which window belongs to it, whether we launched it, etc.</summary>
    internal class ItemRuntime
    {
        public RotationItem Item;
        public IntPtr Hwnd = IntPtr.Zero;
        public bool LaunchedByUs;
        public uint RootPid;              // process we started (or that owns the window)
        public string MatchProcess = "";  // process name used to re-find windows
        public bool SelfFullscreen;       // browser kiosk handles fullscreen itself
        public bool UserProfile;          // website in the person's own browser profile: its browser is shared with their other windows
        public bool F11Failed;            // the browser's own fullscreen (F11) never worked: fall back to ScreenCycle's
        private int f11Misses;
        public string LastError = "";
        public int Failures;

        private DateTime foundAt = DateTime.MinValue;
        private int cachedCaption;
        private bool stylesSaved;
        private long origStyle, origEx;
        private Rectangle origRect;

        public ItemRuntime(RotationItem item) { Item = item; }

        public static string Signature(RotationItem i)
        {
            return string.Join("|", new string[] {
                i.Kind.ToString(), i.Url.Trim(), i.Browser.ToString(), i.BrowserProfile ?? "", i.Path.Trim(), i.Arguments.Trim(),
                i.TitleContains.Trim(), i.ProcessName.Trim(),
                (i.Kind == ItemKind.Website ? i.Mode.ToString() : "") });
        }

        public bool IsAlive { get { return WindowTools.IsAlive(Hwnd); } }

        // ------------------------------------------------------------------ matching

        private static bool TitleOk(RotationItem item, WindowInfo w)
        {
            if (string.IsNullOrWhiteSpace(item.TitleContains)) return true;
            return w.Title.IndexOf(item.TitleContains.Trim(), StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string NormProc(string p)
        {
            p = (p ?? "").Trim();
            if (p.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)) p = p.Substring(0, p.Length - 4);
            return p;
        }

        public static bool MatchesWindowItem(RotationItem item, WindowInfo w)
        {
            bool hasTitle = !string.IsNullOrWhiteSpace(item.TitleContains);
            string proc = NormProc(item.ProcessName);
            if (!hasTitle && proc.Length == 0) return false;
            if (!TitleOk(item, w)) return false;
            if (proc.Length > 0 && !string.Equals(proc, w.ProcessName, StringComparison.OrdinalIgnoreCase)) return false;
            return true;
        }

        /// <summary>Looks for an existing window that belongs to this item (no launching). Cheap enough for the UI thread.</summary>
        public bool TryRefind(ICollection<IntPtr> claimed)
        {
            if (IsAlive) return true;
            List<WindowInfo> wins = WindowTools.ListAppWindows(true);
            WindowInfo best = null;
            if (Item.Kind == ItemKind.Window)
            {
                foreach (WindowInfo w in wins)
                {
                    if (claimed.Contains(w.Handle)) continue;
                    if (MatchesWindowItem(Item, w)) { best = Pick(best, w); }
                }
            }
            else if (RootPid != 0 && !UserProfile)
            {
                Dictionary<uint, uint> parents = WindowTools.ParentMap();
                foreach (WindowInfo w in wins)
                {
                    if (claimed.Contains(w.Handle)) continue;
                    if (!TitleOk(Item, w)) continue;
                    bool inTree = WindowTools.IsInTree(w.Pid, RootPid, parents);
                    bool sameProc = Item.Kind == ItemKind.Application && MatchProcess.Length > 0
                        && string.Equals(w.ProcessName, MatchProcess, StringComparison.OrdinalIgnoreCase)
                        && !string.IsNullOrWhiteSpace(Item.TitleContains);
                    if (inTree || sameProc) best = Pick(best, w);
                }
            }
            if (best != null)
            {
                Adopt(best.Handle);
                return true;
            }
            return false;
        }

        private static WindowInfo Pick(WindowInfo a, WindowInfo b)
        {
            if (a == null) return b;
            Rectangle ra = WindowTools.GetRect(a.Handle), rb = WindowTools.GetRect(b.Handle);
            return (long)rb.Width * rb.Height > (long)ra.Width * ra.Height ? b : a;
        }

        private void Adopt(IntPtr h)
        {
            if (h != Hwnd) { stylesSaved = false; cachedCaption = 0; foundAt = DateTime.UtcNow; }
            Hwnd = h;
            uint pid = WindowTools.GetPid(h);
            if (RootPid == 0) RootPid = pid;
            if (MatchProcess.Length == 0) MatchProcess = WindowTools.GetProcessName(pid);
            Failures = 0;
            LastError = "";
            if (UserProfile) WindowMemory.Remember(Item.Id, h);
        }

        // ------------------------------------------------------------------ launching

        /// <summary>Makes sure the item has a window, launching it if needed. Runs on the UI thread, awaits between polls.</summary>
        public async Task<bool> EnsureAsync(ICollection<IntPtr> claimed, Rectangle bounds, int timeoutMs, Func<bool> cancelled)
        {
            if (IsAlive) return true;
            if (TryRefind(claimed)) return true;
            try
            {
                switch (Item.Kind)
                {
                    case ItemKind.Window:
                        LastError = "No open window matches " + Item.TargetDescription;
                        // the window might appear later (someone opens it) - wait a little
                        return await WaitForExisting(claimed, Math.Min(timeoutMs, 3000), cancelled);
                    case ItemKind.Website:
                        return await LaunchWebsite(claimed, bounds, timeoutMs, cancelled);
                    default:
                        return await LaunchApplication(claimed, timeoutMs, cancelled);
                }
            }
            catch (Exception ex)
            {
                LastError = ex.Message;
                Log.Error("Launching '" + Item.DisplayName + "' failed: " + ex);
                Failures++;
                return false;
            }
        }

        private async Task<bool> WaitForExisting(ICollection<IntPtr> claimed, int timeoutMs, Func<bool> cancelled)
        {
            Stopwatch sw = Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < timeoutMs)
            {
                if (cancelled()) return false;
                await Task.Delay(300);
                if (TryRefind(claimed)) return true;
            }
            Failures++;
            return false;
        }

        private static HashSet<IntPtr> Snapshot()
        {
            HashSet<IntPtr> set = new HashSet<IntPtr>();
            foreach (WindowInfo w in WindowTools.ListAppWindows(false)) set.Add(w.Handle);
            return set;
        }

        private async Task<bool> LaunchWebsite(ICollection<IntPtr> claimed, Rectangle bounds, int timeoutMs, Func<bool> cancelled)
        {
            if (string.IsNullOrWhiteSpace(Item.Url)) { LastError = "No URL set"; Failures++; return false; }
            BrowserLaunch bl = Browsers.Build(Item, bounds);

            if (bl != null && bl.UserProfile)
            {
                UserProfile = true;
                F11Failed = false;
                f11Misses = 0;
                MatchProcess = bl.ProcessName;
                SelfFullscreen = false;
                // The window opened last time (ScreenCycle restarted, browser kept running)? Use it again.
                IntPtr known = WindowMemory.Recall(Item.Id, bl.ProcessName);
                if (known != IntPtr.Zero && !claimed.Contains(known))
                {
                    RootPid = WindowTools.GetPid(known);
                    Adopt(known);
                    LaunchedByUs = true;
                    Log.Info("Reusing the window opened earlier for '" + Item.DisplayName + "'");
                    return true;
                }
                HashSet<IntPtr> before = Snapshot();
                ProcessStartInfo psi = new ProcessStartInfo(bl.Exe, bl.Args);
                psi.UseShellExecute = false;
                psi.WorkingDirectory = Path.GetDirectoryName(bl.Exe);
                Log.Info("Launching '" + Item.DisplayName + "' with the browser's own profile: " + bl.Exe + " " + bl.Args);
                Process p = Process.Start(psi);
                RootPid = p != null ? (uint)p.Id : 0;
                LaunchedByUs = true;
                return await WaitForNewWindow(before, claimed, timeoutMs, bl.ProcessName, false, cancelled);
            }
            UserProfile = false;

            if (bl != null)
            {
                // A browser left running from a previous session with this item's private profile? Reuse it.
                string marker = Item.Id;
                string procName = bl.ProcessName;
                uint existing = await Task.Run(delegate { return FindProcessWithMarker(procName + ".exe", marker); });
                if (existing != 0)
                {
                    RootPid = existing;
                    MatchProcess = procName;
                    SelfFullscreen = bl.SelfFullscreen;
                    if (TryRefind(claimed))
                    {
                        LaunchedByUs = true;
                        Log.Info("Reusing running browser for '" + Item.DisplayName + "'");
                        return true;
                    }
                }

                HashSet<IntPtr> before = Snapshot();
                ProcessStartInfo psi = new ProcessStartInfo(bl.Exe, bl.Args);
                psi.UseShellExecute = false;
                psi.WorkingDirectory = Path.GetDirectoryName(bl.Exe);
                Log.Info("Launching '" + Item.DisplayName + "': " + bl.Exe + " " + bl.Args);
                Process p = Process.Start(psi);
                RootPid = p != null ? (uint)p.Id : 0;
                MatchProcess = bl.ProcessName;
                SelfFullscreen = bl.SelfFullscreen;
                LaunchedByUs = true;
                return await WaitForNewWindow(before, claimed, timeoutMs, bl.ProcessName, false, cancelled);
            }
            else
            {
                if (Item.Browser != BrowserKind.Default)
                    Log.Warn("No supported browser found, opening '" + Item.Url + "' with the default browser");
                HashSet<IntPtr> before = Snapshot();
                ProcessStartInfo psi = new ProcessStartInfo(Browsers.NormalizeUrl(Item.Url));
                psi.UseShellExecute = true;
                Process.Start(psi);
                RootPid = 0;
                MatchProcess = "";
                SelfFullscreen = false;
                LaunchedByUs = false; // the default browser may be the user's own session: never close it
                return await WaitForNewWindow(before, claimed, timeoutMs, "", true, cancelled);
            }
        }

        private static uint FindProcessWithMarker(string exeName, string marker)
        {
            try
            {
                using (ManagementObjectSearcher s = new ManagementObjectSearcher(
                    "SELECT ProcessId, CommandLine FROM Win32_Process WHERE Name = '" + exeName.Replace("'", "") + "'"))
                {
                    foreach (ManagementObject mo in s.Get())
                    {
                        string cl = mo["CommandLine"] as string;
                        if (cl != null && cl.IndexOf(marker, StringComparison.OrdinalIgnoreCase) >= 0
                            && cl.IndexOf("--type=", StringComparison.OrdinalIgnoreCase) < 0
                            && cl.IndexOf("-contentproc", StringComparison.OrdinalIgnoreCase) < 0)
                            return Convert.ToUInt32(mo["ProcessId"]);
                    }
                }
            }
            catch (Exception ex) { Log.Warn("Process lookup failed: " + ex.Message); }
            return 0;
        }

        private async Task<bool> LaunchApplication(ICollection<IntPtr> claimed, int timeoutMs, Func<bool> cancelled)
        {
            string path = Environment.ExpandEnvironmentVariables((Item.Path ?? "").Trim().Trim('"'));
            if (path.Length == 0) { LastError = "No program set"; Failures++; return false; }

            bool isExe = path.EndsWith(".exe", StringComparison.OrdinalIgnoreCase);
            MatchProcess = NormProc(Item.ProcessName);
            if (MatchProcess.Length == 0 && isExe) MatchProcess = Path.GetFileNameWithoutExtension(path);

            // With a title filter, an already-open matching window is adopted instead of launching a duplicate.
            if (!string.IsNullOrWhiteSpace(Item.TitleContains))
            {
                foreach (WindowInfo w in WindowTools.ListAppWindows(true))
                {
                    if (claimed.Contains(w.Handle) || !TitleOk(Item, w)) continue;
                    if (MatchProcess.Length > 0 && !string.Equals(MatchProcess, w.ProcessName, StringComparison.OrdinalIgnoreCase)) continue;
                    Adopt(w.Handle);
                    LaunchedByUs = false;
                    Log.Info("Adopted existing window for '" + Item.DisplayName + "': " + w.Title);
                    return true;
                }
            }

            HashSet<IntPtr> before = Snapshot();
            ProcessStartInfo psi = new ProcessStartInfo(path, Environment.ExpandEnvironmentVariables(Item.Arguments ?? ""));
            psi.UseShellExecute = true;
            try
            {
                string dir = Path.GetDirectoryName(path);
                if (!string.IsNullOrEmpty(dir) && Directory.Exists(dir)) psi.WorkingDirectory = dir;
            }
            catch { }
            Log.Info("Launching '" + Item.DisplayName + "': " + path + " " + Item.Arguments);
            Process p = Process.Start(psi);
            RootPid = 0;
            try { if (p != null) RootPid = (uint)p.Id; } catch { }
            LaunchedByUs = true;
            return await WaitForNewWindow(before, claimed, timeoutMs, MatchProcess, true, cancelled);
        }

        private async Task<bool> WaitForNewWindow(HashSet<IntPtr> before, ICollection<IntPtr> claimed, int timeoutMs,
            string procName, bool allowAnyNew, Func<bool> cancelled)
        {
            Stopwatch sw = Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < timeoutMs)
            {
                if (cancelled()) return false;
                await Task.Delay(250);
                List<WindowInfo> wins = WindowTools.ListAppWindows(true);
                Dictionary<uint, uint> parents = WindowTools.ParentMap();
                WindowInfo best = null;
                int bestScore = 0;
                foreach (WindowInfo w in wins)
                {
                    if (before.Contains(w.Handle) || claimed.Contains(w.Handle)) continue;
                    if (!TitleOk(Item, w)) continue;
                    int score = 0;
                    if (RootPid != 0 && WindowTools.IsInTree(w.Pid, RootPid, parents)) score = 3;
                    else if (procName.Length > 0 && string.Equals(w.ProcessName, procName, StringComparison.OrdinalIgnoreCase)) score = 2;
                    else if (allowAnyNew && sw.ElapsedMilliseconds > 1500) score = 1; // e.g. UWP apps, documents
                    if (score > bestScore || (score == bestScore && score > 0 && Pick(best, w) == w)) { best = w; bestScore = score; }
                }
                if (best != null)
                {
                    // give splash screens a moment to be replaced by the real window
                    if (bestScore < 3 || sw.ElapsedMilliseconds < 800) await Task.Delay(400);
                    if (!WindowTools.IsAlive(best.Handle)) continue;
                    Adopt(best.Handle);
                    if (RootPid == 0 || bestScore < 3) RootPid = best.Pid;
                    Log.Info("Window found for '" + Item.DisplayName + "' after " + sw.ElapsedMilliseconds + " ms: " + best.Title + " [" + best.ProcessName + "]");
                    return true;
                }

                // Single-instance apps hand the request to an already running copy and exit.
                if (sw.ElapsedMilliseconds > 5000 && Item.Kind == ItemKind.Application && procName.Length > 0)
                {
                    foreach (WindowInfo w in wins)
                    {
                        if (claimed.Contains(w.Handle) || !TitleOk(Item, w)) continue;
                        if (string.Equals(w.ProcessName, procName, StringComparison.OrdinalIgnoreCase))
                        {
                            Adopt(w.Handle);
                            RootPid = w.Pid;
                            LaunchedByUs = false;
                            Log.Info("Using existing window of " + procName + " for '" + Item.DisplayName + "'");
                            return true;
                        }
                    }
                }
            }
            LastError = "No window appeared within " + (timeoutMs / 1000) + " s";
            Failures++;
            Log.Warn("'" + Item.DisplayName + "': " + LastError);
            return false;
        }

        // ------------------------------------------------------------------ presentation

        public void ApplyMode(Rectangle bounds)
        {
            if (!IsAlive) return;
            switch (Item.Mode)
            {
                case WindowMode.Fullscreen:
                    if (UserProfile && !F11Failed)
                    {
                        // fullscreen comes from the browser's own F11 (see WantsFullscreenKey); just keep it on the right display
                        if (Native.IsIconic(Hwnd)) Native.ShowWindow(Hwnd, Native.SW_RESTORE);
                        if (!CoversScreen(bounds)) WindowTools.MoveOnto(Hwnd, bounds);
                        return;
                    }
                    if (SelfFullscreen)
                    {
                        if (Native.IsIconic(Hwnd)) Native.ShowWindow(Hwnd, Native.SW_RESTORE);
                        Rectangle r = WindowTools.GetRect(Hwnd);
                        if (r.Contains(bounds)) return;   // kiosk window already covers the screen
                        // the browser switches to kiosk a moment after its window appears: don't interfere meanwhile
                        if ((DateTime.UtcNow - foundAt).TotalSeconds < 8 && Item.Kind == ItemKind.Website) return;
                    }
                    SaveStyles();
                    WindowTools.FitFullscreen(Hwnd, bounds, Item.TitleBarCrop, ref cachedCaption);
                    break;
                case WindowMode.Maximized:
                    WindowTools.MaximizeOn(Hwnd, bounds);
                    break;
            }
        }

        public bool CoversScreen(Rectangle bounds)
        {
            return IsAlive && WindowTools.GetRect(Hwnd).Contains(bounds);
        }

        /// <summary>True when the browser's own fullscreen (F11) should be switched on now (window has the focus).</summary>
        public bool WantsFullscreenKey(Rectangle bounds)
        {
            return UserProfile && !F11Failed && Item.Mode == WindowMode.Fullscreen && IsAlive && !CoversScreen(bounds)
                && Native.GetForegroundWindow() == Hwnd;
        }

        /// <summary>After F11 was sent: if the window still doesn't cover the screen, use ScreenCycle's own fullscreen instead.</summary>
        public void CheckFullscreenKey(Rectangle bounds)
        {
            if (!IsAlive) return;
            if (CoversScreen(bounds)) { f11Misses = 0; return; }
            // A browser dialog (restore session, first-run...) can swallow the key: maximize for now, retry next turn.
            if (++f11Misses < 3)
            {
                Log.Info("'" + Item.DisplayName + "': F11 had no effect (dialog open?), will try again next time");
                WindowTools.MaximizeOn(Hwnd, bounds);
                return;
            }
            F11Failed = true;
            Log.Warn("'" + Item.DisplayName + "': the browser did not go fullscreen with F11, ScreenCycle fits the window instead");
        }
        private void SaveStyles()
        {
            if (stylesSaved) return;
            origStyle = Native.GetWindowLong(Hwnd, Native.GWL_STYLE);
            origEx = Native.GetWindowLong(Hwnd, Native.GWL_EXSTYLE);
            Native.WINDOWPLACEMENT wp = new Native.WINDOWPLACEMENT();
            wp.length = System.Runtime.InteropServices.Marshal.SizeOf(typeof(Native.WINDOWPLACEMENT));
            if (Native.IsZoomed(Hwnd) || Native.IsIconic(Hwnd))
            {
                Native.GetWindowPlacement(Hwnd, ref wp);
                origRect = Rectangle.FromLTRB(wp.rcNormalPosition.Left, wp.rcNormalPosition.Top, wp.rcNormalPosition.Right, wp.rcNormalPosition.Bottom);
            }
            else origRect = WindowTools.GetRect(Hwnd);
            stylesSaved = true;
        }

        /// <summary>Gives a window we did not launch its frame back.</summary>
        public void RestoreIfAdopted()
        {
            if (LaunchedByUs || !stylesSaved || !IsAlive) { stylesSaved = false; return; }
            WindowTools.RestoreStyles(Hwnd, origStyle, origEx, origRect);
            stylesSaved = false;
        }

        public void Release(bool closeLaunched)
        {
            try
            {
                if (LaunchedByUs && closeLaunched)
                {
                    if (IsAlive) Native.PostMessage(Hwnd, Native.WM_CLOSE, IntPtr.Zero, IntPtr.Zero);
                }
                else RestoreIfAdopted();
            }
            catch (Exception ex) { Log.Warn("Release failed: " + ex.Message); }
            Hwnd = IntPtr.Zero;
        }
    }

    /// <summary>
    /// Remembers which window was opened for a screen that uses the person's own browser profile. That browser keeps
    /// running when ScreenCycle exits, so the next start can take the same window again instead of opening a duplicate.
    /// </summary>
    internal static class WindowMemory
    {
        private static string FilePath { get { return Path.Combine(AppConfig.DataDir, "windows.txt"); } }

        private static Dictionary<string, long> Load()
        {
            Dictionary<string, long> d = new Dictionary<string, long>();
            try
            {
                if (!File.Exists(FilePath)) return d;
                foreach (string line in File.ReadAllLines(FilePath))
                {
                    string[] p = line.Split('|');
                    long h;
                    if (p.Length == 2 && long.TryParse(p[1], out h)) d[p[0]] = h;
                }
            }
            catch { }
            return d;
        }

        public static void Remember(string itemId, IntPtr hwnd)
        {
            try
            {
                Dictionary<string, long> d = Load();
                d[itemId] = hwnd.ToInt64();
                List<string> lines = new List<string>();
                foreach (KeyValuePair<string, long> kv in d)
                    if (WindowTools.IsAlive(new IntPtr(kv.Value))) lines.Add(kv.Key + "|" + kv.Value);
                Directory.CreateDirectory(AppConfig.DataDir);
                File.WriteAllLines(FilePath, lines.ToArray());
            }
            catch (Exception ex) { Log.Warn("Window memory: " + ex.Message); }
        }

        /// <summary>The remembered window, if it still exists and still belongs to that browser.</summary>
        public static IntPtr Recall(string itemId, string processName)
        {
            long v;
            if (!Load().TryGetValue(itemId, out v)) return IntPtr.Zero;
            IntPtr h = new IntPtr(v);
            if (!WindowTools.IsAlive(h) || !WindowTools.IsAppWindow(h)) return IntPtr.Zero;
            if (!string.Equals(WindowTools.GetProcessName(WindowTools.GetPid(h)), processName, StringComparison.OrdinalIgnoreCase)) return IntPtr.Zero;
            return h;
        }
    }
}
